package com.anamcara.service;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import software.amazon.awssdk.core.ResponseInputStream;import software.amazon.awssdk.regions.Region;import software.amazon.awssdk.services.s3.S3Client;import software.amazon.awssdk.services.s3.model.*;import java.io.IOException;import java.util.*;
@Service public class S3MediaService{private static final Set<String>ALLOWED=Set.of("image/jpeg","image/png","image/webp","image/gif","video/mp4","video/webm","video/quicktime");private final S3Client s3;private final String bucket;public S3MediaService(@Value("${aws.region}")String region,@Value("${app.media.s3.bucket}")String bucket){this.s3=S3Client.builder().region(Region.of(region)).build();this.bucket=bucket;}
public StoredMedia store(MultipartFile file)throws IOException{String mime=file.getContentType();if(mime==null||!ALLOWED.contains(mime))throw new IllegalArgumentException("Only common image and video files are supported.");String original=Optional.ofNullable(file.getOriginalFilename()).orElse("");String ext=original.lastIndexOf('.')>=0?original.substring(original.lastIndexOf('.')).toLowerCase():"";String key=UUID.randomUUID()+ext;s3.putObject(PutObjectRequest.builder().bucket(bucket).key(key).contentType(mime).build(),software.amazon.awssdk.core.sync.RequestBody.fromInputStream(file.getInputStream(),file.getSize()));return new StoredMedia(key,mime.startsWith("video/")?"VIDEO":"IMAGE");}
public void delete(String key){if(key!=null&&!key.isBlank())s3.deleteObject(DeleteObjectRequest.builder().bucket(bucket).key(key).build());}public HeadObjectResponse head(String key){return s3.headObject(HeadObjectRequest.builder().bucket(bucket).key(key).build());}public ResponseInputStream<GetObjectResponse> open(String key){return s3.getObject(GetObjectRequest.builder().bucket(bucket).key(key).build());}public record StoredMedia(String key,String mediaType){}
}
